create or replace view t1 as select c_customer_sk from customer, customer_address where c_current_addr_sk = ca_address_sk and substring(ca_zip,1,5) <> substring(ca_zip,1,5) and ca_state = 'CA' and c_birth_month = 6 group by c_customer_sk;
create or replace view t2 as select d_date_sk from date_dim where d_year = 2000 and d_moy = 8 group by d_date_sk;
create or replace view t3 as select ss_item_sk, min(ss_ext_sales_price) as min_ss_ext_sales_price from store_sales, store, t1, t2 where ss_sold_date_sk = d_date_sk and ss_store_sk = s_store_sk and ss_customer_sk = c_customer_sk and ss_wholesale_cost between 0 and 70 group by ss_item_sk;
select min(i_brand_id), min(i_manufact_id), min(min_ss_ext_sales_price) from item, t3 where i_item_sk = ss_item_sk and i_category = 'Electronics';